effect.shader:
vec3 sat3v(vec3 c){ return clamp(c, vec3(0.0), vec3(1.0)); }

// LAYER -> SCREEN. The bend is computed from layer coordinates and every read
// goes back through the layer transform.
// Positions are anchored on acScreenNorm - the engine's own screen position for
// this fragment - so the anchor never depends on the matrix. Only the DELTA goes
// through acLayerToScreen, and the w=0 multiply cancels the translation, so a
// layer-space offset becomes a screen-space offset exactly. fetchL(acLayerNorm)
// therefore returns texture2DCv(inputImg.texture, acScreenNorm), the engine idiom.
vec2 lpToScreen(vec2 v){ return acScreenNorm + (vec4(v - acLayerNorm, 0.0, 0.0) * acLayerToScreen).xy; }
vec4 fetchL(vec2 lp){ return texture2DCv(inputImg.texture, clamp(lpToScreen(lp), 0.0, 1.0)); }

vec2 rot2(vec2 p, float a){ float c = cos(a); float s = sin(a); return vec2(p.x * c - p.y * s, p.x * s + p.y * c); }

vec2 edgeFix(vec2 lp){
if (edgeMode <= 0) return clamp(lp, 0.0, 1.0);
if (edgeMode <= 1){
vec2 m = mod(lp, vec2(2.0, 2.0));
return abs(m - vec2(1.0, 1.0)) * -1.0 + vec2(1.0);
}
return fract(lp);
}

void main(){
vec2 lp  = acLayerNorm;
vec4 src = fetchL(lp);

float al = max(src.a, 1.0e-4);
vec3 sc = src.rgb / al;

float asp = acLayerSize.x / max(acLayerSize.y, 1.0);
vec2  q   = vec2((lp.x - 0.5) * asp, lp.y - 0.5);

// ---- pick the bend axis -------------------------------------------------
// u runs -1..1 along the bending axis, v is the perpendicular coordinate.
float u;
float v;
if (bendAxis <= 0){
u = (lp.x - anchor) * 2.0;
v = lp.y;
} else if (bendAxis <= 1){
u = (lp.y - anchor) * 2.0;
v = lp.x;
} else {
// Radial: bend outward from the centre, so u is the radius.
u = length(q) * 2.0;
v = atan(q.y, q.x) / 6.2831853 + 0.5;
}

// ---- half angle ---------------------------------------------------------
// S-Curve flips the sign of the bend across the perpendicular axis. A smooth
// flip rather than sign() so the reversal has no crease in it.
float th = bend * 2.60;
if (curveMode >= 4 && curveMode <= 4){
th *= mix(-1.0, 1.0, smoothstep(0.0, 1.0, clamp(v, 0.0, 1.0)));
}

// ---- cylindrical mapping ------------------------------------------------
// R * sin(a) with R = 1/th keeps this an identity as th -> 0, so bend 0 is a
// true no-op rather than a near-miss.
float a    = u * th;
float R    = 1.0 / max(abs(th), 1.0e-4);
float X    = R * sin(a);
float Z    = R * (cos(a) - 1.0);
float pAmt = perspective;
if (curveMode <= 1) pAmt *= 0.85;
if (curveMode >= 2 && curveMode <= 2) pAmt *= 0.25;
if (curveMode >= 5) pAmt = max(pAmt, 0.70);
float persp = 1.0 / max(1.0 + Z * pAmt * 1.7, 0.06);

// Profile blends between a flat linear map and the full arc, so the same bend
// amount can be a gentle roll or a tight tube.
float nu = mix(u, X * persp, clamp(profile, 0.0, 1.0));

// ---- rebuild the sample coordinate -------------------------------------
float su;
float sv;
if (bendAxis <= 0){
su = anchor + nu * 0.5;
sv = (v - 0.5) * persp + 0.5;
} else if (bendAxis <= 1){
sv = anchor + nu * 0.5;
su = (v - 0.5) * persp + 0.5;
} else {
// Radial bend: keep the angle, bend the radius.
float rad = clamp(nu * 0.5, 0.0, 1.4);
su = 0.5 + cos(v * 6.2831853) * rad / max(asp, 1.0e-3);
sv = 0.5 + sin(v * 6.2831853) * rad;
}

vec2 sp = vec2(su, sv);

// ---- twist --------------------------------------------------------------
if (abs(twist) > 0.001){
sp = vec2(0.5) + rot2(sp - vec2(0.5), twist * nu * 0.85);
}

vec4 got = texture2DCv(inputImg.texture, clamp(lpToScreen(edgeFix(sp)), 0.0, 1.0));
float ga = max(got.a, 1.0e-4);
vec3 gc  = got.rgb / ga;

// ---- shading ------------------------------------------------------------
// The surface tangent is (dX, dZ) = (cos a, -sin a); rotating it 90 degrees in
// the x-z plane gives the normal, which is what the light is dotted against.
float sh = 1.0;
if (shading > 0.001 || sheen > 0.001){
vec2  nrm = normalize(vec2(sin(a), cos(a)) + vec2(1.0e-5));
float la  = radians(lightAngle);
vec3  L   = normalize(vec3(cos(la), 0.0, sin(la)));
vec3  N   = normalize(vec3(nrm.x, 0.0, nrm.y));
float dp  = clamp(dot(N, L), 0.0, 1.0);
sh = mix(1.0, 0.42 + 1.00 * dp, clamp(shading, 0.0, 1.0));
gc *= sh;
if (sheen > 0.001){
// A tight specular band that travels along the crest of the curve.
float sp2 = pow(dp, 9.0) * sheen * 0.65;
gc += vec3(sp2);
}
}

vec3  col = mix(sc, gc, mixAmt);
float oA  = got.a * opacity;
gl_FragColor = vec4(col * oA, oA);
}
